# Triage group definitions. G(ids, owner, fix, **kw)
# kw: title, rec(fix-now|defer|wont-fix|decide), scope(frontend|backend|shared-package|decision|proposal),
#     wave, est, sev, area, cat, dec (decision id), note, known (extra knownRefs), kstat
GROUPS = []


def G(ids, owner, fix, **kw):
    GROUPS.append(dict(ids=ids, owner=owner, fix=fix, **kw))


